import Ajv, {type ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
}

const ajvOptions = {strict: false, validateFormats: false};

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly schemaValidator = new Ajv(ajvOptions);
  private readonly validators = new WeakMap<Record<string, unknown>, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private validatorFor(definition: ToolDefinition): ValidateFunction {
    const cached = this.validators.get(definition.inputSchema);
    if (cached) return cached;

    try {
      const validator = this.schemaValidator.compile(definition.inputSchema);
      this.validators.set(definition.inputSchema, validator);
      return validator;
    } catch (error) {
      const message = error instanceof Error ? error.message : 'unknown schema error';
      throw new Error(`Invalid inputSchema for tool ${definition.name}: ${message}`, {cause: error});
    }
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    if (typeof definition !== 'function') {
      this.validatorFor(resolved);
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Returns input-schema rejections; see specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    const validator = this.validatorFor(definition);
    if (!validator(input)) return {result: formatValidationErrors(validator.errors)};
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

interface ValidationError {
  keyword: string;
  instancePath?: string;
  message?: string;
  params: object;
}

function formatValidationErrors(errors: ValidationError[] | null | undefined): string {
  if (!errors?.length) return 'Tool input does not match the declared schema.';

  return errors.map(formatValidationError).join('; ');
}

function formatValidationError(error: ValidationError): string {
  if (error.keyword === 'required') {
    return `${joinInstancePath(error.instancePath, validationParameter(error, 'missingProperty'))} is required.`;
  }
  if (error.keyword === 'type') {
    return `${error.instancePath || '/'} must be a ${String(validationParameter(error, 'type'))}.`;
  }
  if (error.keyword === 'enum') {
    return `${error.instancePath || '/'} must match an allowed value.`;
  }
  return `${error.instancePath || '/'} ${error.message ?? 'does not match the declared schema'}.`;
}

function validationParameter(error: ValidationError, parameter: string): unknown {
  return (error.params as Record<string, unknown>)[parameter];
}

function joinInstancePath(instancePath: string | undefined, property: unknown): string {
  return `${instancePath || ''}/${String(property)}`;
}
import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('uses the current schema from a function-valued definition source', async () => {
    const registry = new ToolRegistry();
    let useLocationSchema = false;
    const executorCalls: Array<Record<string, unknown>> = [];

    registry.register(
      () => ({
        name: 'weather',
        description: 'Gets weather',
        inputSchema: useLocationSchema
          ? {type: 'object', properties: {location: {type: 'string'}}, required: ['location']}
          : {type: 'object', properties: {city: {type: 'string'}}, required: ['city']},
      }),
      async input => {
        executorCalls.push(input);
        return 'sunny';
      }
    );

    const cityResponse = await registry.execute('weather', {city: 'Paris'});
    useLocationSchema = true;
    const staleInputResponse = await registry.execute('weather', {city: 'Paris'});
    const locationResponse = await registry.execute('weather', {location: 'Paris'});

    expect({cityResponse, staleInputResponse, locationResponse, executorCalls}).toEqual({
      cityResponse: {result: 'sunny'},
      staleInputResponse: {result: expect.stringContaining('location')},
      locationResponse: {result: 'sunny'},
      executorCalls: [{city: 'Paris'}, {location: 'Paris'}],
    });
  });

  it('names the complete path for a nested missing required property', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'Gets weather',
        inputSchema: {
          type: 'object',
          properties: {
            location: {
              type: 'object',
              properties: {postalCode: {type: 'string'}},
              required: ['postalCode'],
            },
          },
          required: ['location'],
        },
      },
      async () => 'sunny'
    );

    const response = await registry.execute('weather', {location: {}});

    expect(response).toEqual({result: expect.stringMatching(/\/location\/postalCode.*required/i)});
  });
});
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L21)).
- A rejection for a nested missing required property identifies its complete JSON Pointer path as well as the required constraint ([validated by: names the complete path for a nested missing required property](../../src/orchestration/tools/registry.test.ts#L36)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L51)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults.
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L98)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema`.
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules ([validated by: uses the current schema from a function-valued definition source](../../src/orchestration/tools/registry.test.ts#L4)).

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L117)).
